TypeScript - async iterator streaming with resume token (recommended):

import { RedwoodClient, Idempotency } from '@redwood/inference'

const client = new RedwoodClient({
  retryConfig: { maxAttempts: 3, initialBackoffMs: 100, multiplier: 2.0, maxBackoffMs: 2000, jitterFraction: 0.25 }
})

const idKey = Idempotency.generate()
const stream = client.streamPredict({ prompt: 'long prompt', headers: Idempotency.asHeaders(idKey) })

for await (const chunk of stream) {
  if (chunk.resumeToken) {
    // persist resumeToken to resume later if we fail midway
    saveResumeToken(chunk.resumeToken)
  }
  processChunk(chunk)
}

// To resume:
// client.streamPredict({ resumeToken: loadResumeToken(), headers: Idempotency.asHeaders(idKey) })

Go - context-managed retry wrapper example:

ctx := context.Background()
client := redwood.NewClient(redwood.RetryConfig{MaxAttempts:3, InitialBackoffMs:100, Multiplier:2.0, MaxBackoffMs:2000, JitterFraction:0.25})

hdrs := http.Header{}
key := redwood.IdempotencyGenerate()
hdrs.Set("X-Redwood-Idempotency", key)
hdrs.Set("X-Redwood-Idempotency-Expiry", "60")

resp, err := client.CreateDocument(ctx, CreateDocumentRequest{Text: "hello"}, hdrs)
if err != nil {
  // client will have performed retries for transient failures as per default policy
}
fmt.Println(resp)
